// AI Chat for Clixy - readable source.
//
// Sends the selected text (or the whole document) to the AI backend exactly as
// written, like typing a message in a chat, and inserts the reply. There is no
// prompt wrapping, so the backend you selected in Settings decides how to answer.
// With Moonnox selected, your agent handles the request; with OpenAI selected,
// the model does.
//
// The installable artifact is ai-chat.clixy.json.

clixy.registerAction({
  id: 'ask',
  label: 'Send to AI',
  description: 'Send the selected text to the AI backend as-is and insert the reply',
  run: function (text) {
    return clixy.ai(text);
  },
});
